function decodeBase64Sheet(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) {
    out[i] = bin.charCodeAt(i);
  }
  return out;
}

const REF_IDLE_8DIR_SHEET = decodeBase64Sheet(REF_IDLE_8DIR_B64);
const REF_ATK_8DIR_SHEET = decodeBase64Sheet(REF_ATK_8DIR_B64);

